import assert from 'node:assert/strict';

globalThis.window=globalThis;
await import('./pattern.js');

const api=globalThis.PtoModelParallelRankDeck;
const model={id:'openpangu-flash',layerCount:46,routedExperts:256,stageRanges:[[0,11],[12,22],[23,34],[35,45]]};
const plan=api.partitionModel(model,api.DEFAULT_TOPOLOGY);

assert.equal(plan.manifests.length,128);
assert.equal(new Set(plan.coordinates.map(item=>JSON.stringify([item.tp,item.pp,item.cp,item.ep,item.edp]))).size,128);
assert.equal(plan.stats.layerInstances,1472);
assert.equal(plan.stats.staticInstances,64);
assert.deepEqual(plan.manifestByRank.get(0).layerSegments,[{start:0,end:11,stage:0}]);
assert.deepEqual(plan.manifestByRank.get(6).layerSegments,[{start:35,end:45,stage:3}]);
assert.ok(plan.manifestByRank.get(0).staticRoles.includes('input'));
assert.ok(plan.manifestByRank.get(6).staticRoles.includes('output'));
assert.deepEqual(plan.manifestByRank.get(0).expertOwnership.ids,[...Array(32).keys()]);
assert.deepEqual(plan.manifestByRank.get(8).expertOwnership.ids,[...Array(32).keys()].map(value=>value+32));
assert.equal(plan.groups.filter(group=>group.axis==='tp').length,64);
assert.ok(plan.groups.filter(group=>group.axis==='tp').every(group=>group.ranks.length===2));
assert.equal(plan.groups.filter(group=>group.axis==='pp').length,32);
assert.ok(plan.groups.filter(group=>group.axis==='pp').every(group=>group.ranks.length===4));
assert.equal(plan.groups.filter(group=>group.axis==='ep').length,16);
assert.ok(plan.groups.filter(group=>group.axis==='ep').every(group=>group.ranks.length===8));
assert.equal(plan.groups.filter(group=>group.axis==='edp').length,64);
assert.ok(plan.groups.filter(group=>group.axis==='edp').every(group=>group.ranks.length===2));
assert.equal(plan.manifestByRank.get(0).payloadSignature,plan.manifestByRank.get(64).payloadSignature);
const defaultPositions=plan.manifests.map(manifest=>api.layoutPosition(manifest.coordinate,plan.topology));
assert.ok(defaultPositions.every(position=>position.y===0&&position.z===0),'Default 128-Rank layout must be one row');
assert.ok(defaultPositions.every((position,index)=>index===0||position.x>defaultPositions[index-1].x),'Default Rank row must preserve ascending Rank order');
const payloadTemplate={centerX:100,centerY:200};
assert.deepEqual(api.payloadPoint(payloadTemplate,100,200,3),{x:3,y:0,z:0},'Layer deck depth must use the PP X axis');
assert.equal(api.payloadPoint(payloadTemplate,120,200,3).x,3,'Source geometry width must not change Layer depth');
assert.deepEqual(api.ISOMETRIC_POSE,{rx:-35.264,ry:45});
assert.deepEqual(api.normalizeGroupingAxes(['ep','pp','replica','ep']),['pp','ep','edp']);
assert.deepEqual(api.toggleGroupingAxis(['pp'],'ep'),['pp','ep']);
assert.deepEqual(api.toggleGroupingAxis(['pp','ep'],'ep'),['pp']);
const ppLayout=api.buildHierarchicalRankLayout(plan.manifests,['pp']);
assert.equal(ppLayout.positions.size,128);
assert.equal(ppLayout.frames.length,4);
assert.ok(ppLayout.frames.every(frame=>frame.axis==='pp'&&frame.ranks.length===32));
assert.deepEqual([...ppLayout.positions],plan.manifests.map(manifest=>[manifest.rank,api.layoutPosition(manifest.coordinate,plan.topology,'exploded','pp')]),'PP-only cumulative layout must preserve the original PP transform exactly');
const ppEpLayout=api.buildHierarchicalRankLayout(plan.manifests,['pp','ep']);
assert.equal(ppEpLayout.positions.size,128);
assert.equal(new Set([...ppEpLayout.positions.values()].map(position=>`${position.x.toFixed(3)},${position.y.toFixed(3)},${position.z.toFixed(3)}`)).size,128);
assert.equal(ppEpLayout.frames.filter(frame=>frame.axis==='pp').length,4);
assert.equal(ppEpLayout.frames.filter(frame=>frame.axis==='ep').length,32);
assert.ok(ppEpLayout.frames.filter(frame=>frame.axis==='ep').every(frame=>frame.ranks.length===4));
assert.deepEqual(ppEpLayout.frames.filter(frame=>frame.axis==='pp').map(frame=>({center:frame.center,size:frame.size})),ppLayout.frames.map(frame=>({center:frame.center,size:frame.size})),'Adding EP must not move or resize the four PP parent frames');
const ppTpLayout=api.buildHierarchicalRankLayout(plan.manifests,['pp','tp']);
assert.notDeepEqual([...ppTpLayout.positions], [...ppLayout.positions],'Adding TP must physically regroup Rank containers, not only recolor borders');
assert.equal(ppTpLayout.frames.filter(frame=>frame.axis==='tp').length,8);
assert.ok(ppTpLayout.frames.filter(frame=>frame.axis==='tp').every(frame=>frame.ranks.length===16));
assert.deepEqual(ppTpLayout.frames.filter(frame=>frame.axis==='pp').map(frame=>frame.center),ppLayout.frames.map(frame=>frame.center),'TP regrouping must preserve PP parent centers');
assert.equal(ppTpLayout.positions.get(0).y-ppLayout.positions.get(0).y,ppTpLayout.positions.get(8).y-ppLayout.positions.get(8).y,'Every Rank in one TP shard must move as one rigid sub-cube');
assert.throws(()=>api.partitionModel(model,{...api.DEFAULT_TOPOLOGY,worldSize:127}),/worldSize/);
assert.throws(()=>api.partitionModel({...model,stageRanges:[[0,11],[12,22],[23,34],[34,45]]},api.DEFAULT_TOPOLOGY),/exactly once/);

console.log('model-parallel-rank-deck planner assertions passed');
